begin;
create function kapani_private.has_role(r text) returns boolean language sql stable security definer set search_path='' as $$select kapani_private.active() and exists(select 1 from public.user_roles where user_id=auth.uid() and role=r)$$;
revoke all on function kapani_private.has_role(text) from public,anon;
grant execute on function kapani_private.has_role(text) to authenticated;
create table public.applications(id uuid primary key default gen_random_uuid(),applicant_id uuid not null references public.profiles,kind text not null check(kind in('verification','business','permit','initiative','support')),title text not null check(length(title) between 2 and 160),body text not null check(length(body) between 1 and 10000),status text not null default 'pending' check(status in('pending','approved','rejected','needs_info')),reviewer_id uuid references public.profiles,decision text,created_at timestamptz not null default now(),resolved_at timestamptz);
create unique index application_pending_verification on public.applications(applicant_id) where kind='verification' and status='pending';
create table public.businesses(id uuid primary key default gen_random_uuid(),application_id uuid unique references public.applications,owner_id uuid not null references public.profiles,name text not null check(length(name) between 2 and 160),description text not null default '',address text not null default '',account_id uuid not null unique references public.accounts,status text not null default 'active' check(status in('active','suspended','closed')),created_at timestamptz not null default now());
create table public.business_members(business_id uuid references public.businesses,user_id uuid references public.profiles,position text not null,salary bigint not null default 0 check(salary>=0),can_manage_orders boolean not null default false,can_manage_catalog boolean not null default false,active boolean not null default true,joined_at timestamptz not null default now(),primary key(business_id,user_id));
create table public.vacancies(id uuid primary key default gen_random_uuid(),business_id uuid references public.businesses,title text not null check(length(title) between 2 and 160),description text not null,role_code text references public.roles,positions integer not null check(positions between 1 and 100),salary bigint not null default 0 check(salary>=0),active boolean not null default true,created_at timestamptz not null default now(),check(role_code is null or role_code not in('mayor','resident','owner')));
create table public.job_applications(id uuid primary key default gen_random_uuid(),vacancy_id uuid not null references public.vacancies,applicant_id uuid not null references public.profiles,letter text not null check(length(letter) between 1 and 10000),status text not null default 'pending' check(status in('pending','accepted','rejected','withdrawn','ended')),reviewer_id uuid references public.profiles,decision text,created_at timestamptz not null default now(),resolved_at timestamptz);
create unique index one_active_job_application on public.job_applications(vacancy_id,applicant_id) where status in('pending','accepted');
create index applications_queue on public.applications(status,created_at);
create index job_application_queue on public.job_applications(vacancy_id,status);
create table public.service_requests(id uuid primary key default gen_random_uuid(),author_id uuid not null references public.profiles,service text not null check(service in('ksb','hospital','police')),body text not null check(length(body) between 1 and 5000),status text not null default 'new' check(status in('new','accepted','closed')),assignee_id uuid references public.profiles,result text,created_at timestamptz not null default now(),closed_at timestamptz);
create table public.clinic_services(id uuid primary key default gen_random_uuid(),doctor_id uuid not null references public.profiles,title text not null,description text not null default '',price bigint not null check(price between 0 and 10000000),active boolean not null default true);
create table public.clinic_slots(id uuid primary key default gen_random_uuid(),doctor_id uuid not null references public.profiles,starts_at timestamptz not null,unique(doctor_id,starts_at),check(extract(minute from starts_at) in(0,30) and extract(second from starts_at)=0));
create table public.appointments(id uuid primary key default gen_random_uuid(),patient_id uuid not null references public.profiles,slot_id uuid not null references public.clinic_slots,service_id uuid not null references public.clinic_services,price bigint not null check(price>=0),escrow_id uuid not null references public.accounts,status text not null default 'booked' check(status in('booked','cancelled','completed')),idempotency_key uuid not null,created_at timestamptz not null default now(),unique(patient_id,idempotency_key));
create unique index appointment_slot_reserved on public.appointments(slot_id) where status in('booked','completed');
do $$declare t text;begin foreach t in array array['applications','businesses','business_members','vacancies','job_applications','service_requests','clinic_services','clinic_slots','appointments'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);end loop;end $$;
create policy applications_read on public.applications for select to authenticated using(kapani_private.active() and (applicant_id=auth.uid() or kapani_private.mayor()));
grant insert on public.applications to authenticated;
create policy applications_insert on public.applications for insert to authenticated with check(kapani_private.active() and applicant_id=auth.uid() and status='pending' and reviewer_id is null and decision is null and resolved_at is null);
create policy businesses_read on public.businesses for select to authenticated using(kapani_private.active());
grant update(name,description,address) on public.businesses to authenticated;
create policy business_edit on public.businesses for update to authenticated using(owner_id=auth.uid() and kapani_private.active()) with check(owner_id=auth.uid());
create policy business_members_read on public.business_members for select to authenticated using(kapani_private.active() and (user_id=auth.uid() or exists(select 1 from public.businesses where id=business_id and owner_id=auth.uid()) or kapani_private.mayor()));
create policy business_accounts_read on public.accounts for select to authenticated using(kapani_private.active() and exists(select 1 from public.businesses b where b.account_id=accounts.id and b.owner_id=auth.uid()));
create policy business_entries_read on public.entries for select to authenticated using(kapani_private.active() and exists(select 1 from public.businesses b where b.account_id=entries.account_id and b.owner_id=auth.uid()));
create policy business_transactions_read on public.transactions for select to authenticated using(kapani_private.active() and exists(select 1 from public.entries e join public.businesses b on b.account_id=e.account_id where e.transaction_id=transactions.id and b.owner_id=auth.uid()));
create policy vacancies_read on public.vacancies for select to authenticated using(kapani_private.active());
create policy job_applications_read on public.job_applications for select to authenticated using(kapani_private.active() and (applicant_id=auth.uid() or kapani_private.mayor() or exists(select 1 from public.vacancies v join public.businesses b on b.id=v.business_id where v.id=vacancy_id and b.owner_id=auth.uid())));
grant insert on public.job_applications to authenticated;
create policy job_applications_insert on public.job_applications for insert to authenticated with check(kapani_private.active() and applicant_id=auth.uid() and status='pending' and reviewer_id is null and decision is null and resolved_at is null and exists(select 1 from public.vacancies where id=vacancy_id and active));
create policy requests_read on public.service_requests for select to authenticated using(kapani_private.active() and (author_id=auth.uid() or kapani_private.mayor() or kapani_private.has_role(case when service='hospital' then 'doctor' else service end)));
grant insert on public.service_requests to authenticated;
create policy requests_insert on public.service_requests for insert to authenticated with check(kapani_private.active() and author_id=auth.uid() and status='new' and assignee_id is null and result is null and closed_at is null);
create policy clinic_services_read on public.clinic_services for select to authenticated using(kapani_private.active());
create policy clinic_slots_read on public.clinic_slots for select to authenticated using(kapani_private.active());
create policy appointments_read on public.appointments for select to authenticated using(kapani_private.active() and (patient_id=auth.uid() or exists(select 1 from public.clinic_slots s where s.id=slot_id and s.doctor_id=auth.uid())));
create function public.review_application(p_id uuid,p_approve boolean,p_reason text) returns void language plpgsql security definer set search_path='' as $$declare a public.applications;acc uuid;begin
 if not kapani_private.mayor() then raise exception 'Access denied';end if;
 if p_approve is null or p_reason is null or length(trim(p_reason))<3 then raise exception 'Reason required';end if;
 select * into a from public.applications where id=p_id for update;
 if a.id is null or a.applicant_id=auth.uid() then raise exception 'Self approval prohibited';end if;
 if a.status<>'pending' then raise exception 'Already reviewed';end if;
 if p_approve and a.kind='verification' then update public.profiles set verified=true where id=a.applicant_id;end if;
 if p_approve and a.kind='business' then
 if not exists(select 1 from public.profiles where id=a.applicant_id and verified and not blocked) then raise exception 'Applicant not verified';end if;
 insert into public.accounts(kind) values('business') returning id into acc;
 insert into public.businesses(application_id,owner_id,name,description,account_id) values(a.id,a.applicant_id,a.title,a.body,acc);
 insert into public.user_roles(user_id,role,assigned_by) values(a.applicant_id,'owner',auth.uid()) on conflict do nothing;
 end if;
 update public.applications set status=case when p_approve then 'approved' else 'rejected' end,reviewer_id=auth.uid(),decision=p_reason,resolved_at=now() where id=p_id;
 insert into public.audit_log(actor,action,entity,details) values(auth.uid(),'application_review',p_id,jsonb_build_object('approved',p_approve,'reason',p_reason));
 insert into public.notifications(user_id,category,title,body,href) values(a.applicant_id,'administration','Заявка рассмотрена',p_reason,'#civic');
end $$;
create function public.create_vacancy(p_business uuid,p_title text,p_description text,p_positions integer,p_salary bigint,p_role text default null) returns uuid language plpgsql security definer set search_path='' as $$declare v uuid;begin
 if not kapani_private.active() then raise exception 'Access denied';end if;
 if p_business is null then if not kapani_private.mayor() then raise exception 'Access denied';end if;
 else if not exists(select 1 from public.businesses where id=p_business and owner_id=auth.uid() and status='active') or p_role is not null then raise exception 'Access denied';end if;end if;
 insert into public.vacancies(business_id,title,description,positions,salary,role_code) values(p_business,p_title,p_description,p_positions,p_salary,p_role) returning id into v;
 insert into public.audit_log(actor,action,entity) values(auth.uid(),'vacancy_create',v);return v;
end $$;
create function public.review_job(p_id uuid,p_accept boolean,p_reason text) returns void language plpgsql security definer set search_path='' as $$declare j public.job_applications;v public.vacancies;begin
 if not kapani_private.active() then raise exception 'Access denied';end if;
 select * into j from public.job_applications where id=p_id for update;
 select * into v from public.vacancies where id=j.vacancy_id for update;
 if j.id is null or j.applicant_id=auth.uid() then raise exception 'Self approval prohibited';end if;
 if (v.business_id is null and not kapani_private.mayor()) or (v.business_id is not null and not exists(select 1 from public.businesses where id=v.business_id and owner_id=auth.uid() and status='active')) then raise exception 'Access denied';end if;
 if j.status<>'pending' or not v.active then raise exception 'Invalid transition';end if;
 if p_accept is null or p_reason is null or length(trim(p_reason))<3 then raise exception 'Reason required';end if;
 if p_accept then
 if not exists(select 1 from public.profiles where id=j.applicant_id and verified and not blocked) then raise exception 'Applicant not verified';end if;
 if (select count(*) from public.job_applications where vacancy_id=v.id and status='accepted')>=v.positions then raise exception 'Vacancy full';end if;
 if v.business_id is not null then insert into public.business_members(business_id,user_id,position,salary) values(v.business_id,j.applicant_id,v.title,v.salary) on conflict(business_id,user_id) do update set position=excluded.position,salary=excluded.salary,active=true;
 elsif v.role_code is not null then insert into public.user_roles(user_id,role,assigned_by) values(j.applicant_id,v.role_code,auth.uid()) on conflict do nothing;end if;
 end if;
 update public.job_applications set status=case when p_accept then 'accepted' else 'rejected' end,reviewer_id=auth.uid(),decision=p_reason,resolved_at=now() where id=p_id;
 insert into public.audit_log(actor,action,entity,details) values(auth.uid(),'job_review',p_id,jsonb_build_object('accepted',p_accept,'reason',p_reason));
 insert into public.notifications(user_id,category,title,body,href) values(j.applicant_id,'work','Ответ работодателя',p_reason,'#jobs');
end $$;
create function public.handle_request(p_id uuid,p_close boolean,p_result text default '') returns void language plpgsql security definer set search_path='' as $$declare r public.service_requests;begin
 select * into r from public.service_requests where id=p_id for update;
 if r.id is null or not (kapani_private.mayor() or kapani_private.has_role(case when r.service='hospital' then 'doctor' else r.service end)) then raise exception 'Access denied';end if;
 if p_close then if r.status<>'accepted' or (r.assignee_id<>auth.uid() and not kapani_private.mayor()) or length(trim(p_result))<3 then raise exception 'Invalid transition';end if;
 update public.service_requests set status='closed',result=p_result,closed_at=now() where id=r.id;
 else if r.status<>'new' then raise exception 'Already assigned';end if;update public.service_requests set status='accepted',assignee_id=auth.uid() where id=r.id;end if;
 insert into public.audit_log(actor,action,entity) values(auth.uid(),'service_request_update',r.id);
 insert into public.notifications(user_id,category,title,href) values(r.author_id,'administration','Обращение обновлено','#civic');
end $$;
create function public.create_clinic_service(p_title text,p_price bigint) returns uuid language plpgsql security definer set search_path='' as $$declare v uuid;begin if not kapani_private.has_role('doctor') then raise exception 'Access denied';end if;insert into public.clinic_services(doctor_id,title,price) values(auth.uid(),p_title,p_price) returning id into v;return v;end $$;
create function public.create_clinic_slot(p_start timestamptz) returns uuid language plpgsql security definer set search_path='' as $$declare v uuid;begin if not kapani_private.has_role('doctor') or p_start<=now() then raise exception 'Access denied';end if;insert into public.clinic_slots(doctor_id,starts_at) values(auth.uid(),p_start) returning id into v;return v;end $$;
create function public.book_appointment(p_service uuid,p_slot uuid,p_key uuid) returns uuid language plpgsql security definer set search_path='' as $$declare s public.clinic_services;t public.clinic_slots;a public.appointments;esc uuid;w uuid;v uuid;begin
 if not kapani_private.active() or not exists(select 1 from public.profiles where id=auth.uid() and verified) then raise exception 'Municipal verification required';end if;
 if p_key is null then raise exception 'Key required';end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_key::text,3));
 select * into a from public.appointments where patient_id=auth.uid() and idempotency_key=p_key;
 if a.id is not null then if a.slot_id<>p_slot or a.service_id<>p_service then raise exception 'Idempotency conflict';end if;return a.id;end if;
 select * into t from public.clinic_slots where id=p_slot for update;
 select * into s from public.clinic_services where id=p_service and active;
 if t.id is null or s.id is null or t.starts_at<=now() or t.doctor_id<>s.doctor_id or exists(select 1 from public.appointments where slot_id=t.id and status in('booked','completed')) then raise exception 'Slot unavailable';end if;
 insert into public.accounts(kind) values('escrow') returning id into esc;
 select id into w from public.accounts where owner_id=auth.uid() and kind='wallet';
 if s.price>0 then perform kapani_private.move_money(w,esc,s.price,auth.uid(),'clinic_reserve');end if;
 insert into public.appointments(patient_id,slot_id,service_id,price,escrow_id,idempotency_key) values(auth.uid(),t.id,s.id,s.price,esc,p_key) returning id into v;
 insert into public.notifications(user_id,category,title,href) values(t.doctor_id,'clinic','Новая запись на приём','#clinic'),(auth.uid(),'clinic','Запись подтверждена','#clinic');return v;
end $$;
create function public.appointment_action(p_id uuid,p_cancel boolean) returns void language plpgsql security definer set search_path='' as $$declare a public.appointments;t public.clinic_slots;w uuid;begin
 if not kapani_private.active() then raise exception 'Access denied';end if;
 select * into a from public.appointments where id=p_id for update;select * into t from public.clinic_slots where id=a.slot_id;
 if a.id is null or auth.uid() not in(a.patient_id,t.doctor_id) then raise exception 'Access denied';end if;
 if p_cancel then if a.status='cancelled' then return;end if;if a.status<>'booked' or (t.starts_at<=now() and auth.uid()<>t.doctor_id) then raise exception 'Cancellation unavailable';end if;
 select id into w from public.accounts where owner_id=a.patient_id and kind='wallet';
 else if auth.uid()<>t.doctor_id or not kapani_private.has_role('doctor') or t.starts_at>now() then raise exception 'Access denied';end if;if a.status='completed' then return;end if;if a.status<>'booked' then raise exception 'Invalid transition';end if;
 select id into w from public.accounts where owner_id=t.doctor_id and kind='wallet';end if;
 if a.price>0 then perform kapani_private.move_money(a.escrow_id,w,a.price,auth.uid(),case when p_cancel then 'clinic_refund' else 'clinic_settle' end);end if;
 update public.appointments set status=case when p_cancel then 'cancelled' else 'completed' end where id=a.id;
 insert into public.audit_log(actor,action,entity) values(auth.uid(),case when p_cancel then 'appointment_cancel' else 'appointment_complete' end,a.id);
 insert into public.notifications(user_id,category,title,href) values(a.patient_id,'clinic','Статус приёма обновлён','#clinic');
end $$;
revoke all on function public.review_application(uuid,boolean,text),public.create_vacancy(uuid,text,text,integer,bigint,text),public.review_job(uuid,boolean,text),public.handle_request(uuid,boolean,text),public.create_clinic_service(text,bigint),public.create_clinic_slot(timestamptz),public.book_appointment(uuid,uuid,uuid),public.appointment_action(uuid,boolean) from public,anon;
grant execute on function public.review_application(uuid,boolean,text),public.create_vacancy(uuid,text,text,integer,bigint,text),public.review_job(uuid,boolean,text),public.handle_request(uuid,boolean,text),public.create_clinic_service(text,bigint),public.create_clinic_slot(timestamptz),public.book_appointment(uuid,uuid,uuid),public.appointment_action(uuid,boolean) to authenticated;
commit;
